// Licencias Pro — Control de Vigencia y Renovaciones (solo administración). Panel con indicadores, productos (alta, edición, duplicado,
// stock, desactivación y logos), inventario con búsqueda, entregas confirmadas manualmente, renovaciones, avisos de vencimiento y
// notificaciones por correo. Las credenciales nunca se listan: se muestran una a una, con registro. El servidor vuelve a validar todo.
'use strict';
const licenseState={tab:'panel',product:'',state:'',q:'',from:'',to:''};
const licenseMoney=cents=>cents===null||cents===undefined?'—':'$'+(cents/100).toLocaleString('es-EC',{minimumFractionDigits:2,maximumFractionDigits:2})+' USD';
const licenseDay=value=>{if(!value)return '';const text=String(value);return /^\d{4}-\d{2}-\d{2}$/.test(text)?text.slice(8,10)+'/'+text.slice(5,7)+'/'+text.slice(0,4):formatOrderDate(text);};
const licenseIcons={plus:'M12 5v14 M5 12h14',list:'M3 12h.01 M3 18h.01 M3 6h.01 M8 12h13 M8 18h13 M8 6h13',history:'M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8 M3 3v5h5 M12 7v5l4 2',
 image:'M3 3h18v18H3z M9 9h.01 M21 15l-5-5L5 21',truck:'M14 18V6a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2v11a1 1 0 0 0 1 1h2 M15 18H9 M19 18h2a1 1 0 0 0 1-1v-3.65a1 1 0 0 0-.22-.624l-3.48-4.35A1 1 0 0 0 17.52 8H14',gauge:'M12 14l4-4 M3.34 19a10 10 0 1 1 17.32 0',mail:'m22 7-8.99 5.73a2 2 0 0 1-2.02 0L2 7 M2 4h20v16H2z',cart:'M8 21a1 1 0 1 0 0-2 1 1 0 0 0 0 2 M19 21a1 1 0 1 0 0-2 1 1 0 0 0 0 2 M2.05 2.05h2l2.66 12.42a2 2 0 0 0 2 1.58h9.78a2 2 0 0 0 1.95-1.57l1.65-7.43H5.12'};
let licenseMeta=null;
function licenseBadge(state,label){const badge=el('span',label||licenseMeta?.states?.[state]?.[0]||state,'license-badge');badge.dataset.state=state;return badge;}
// Contador de vigencia: barra con el tiempo restante (verde vigente, amarillo próxima a vencer, rojo vencida, azul pendiente de activación).
async function licenseLoadMeta(){licenseMeta=await api('/api/licenses');return licenseMeta;}
async function renderLicenses(){
 const content=$('module-content');
 // Esqueleto discreto mientras llegan los datos (solo la primera vez; las recargas redibujan sin parpadeos).
 if(!licenseMeta){const ghost=el('div',undefined,'lcat-skeleton');ghost.setAttribute('aria-hidden','true');for(let i=0;i<6;i++)ghost.append(el('span'));const note=el('p','Cargando licencias…','license-sr');note.setAttribute('role','status');content.replaceChildren(note,ghost);}
 try{await licenseLoadMeta();}catch(error){content.replaceChildren(el('p',error.message,'empty-module'));return;}
 content.replaceChildren();const wrap=el('section',undefined,'licenses');content.append(wrap);
 const bar=el('div',undefined,'licenses-actions'),action=(text,icon,run,kind='secondary')=>{const b=button('',run,kind);b.append(systemIcon(licenseIcons[icon]),el('span',text));bar.append(b);return b;};
 action('Registrar nueva licencia','plus',()=>licenseNewDialog(null),'primary');action('Vender o entregar','cart',()=>licenseSaleDialog({}));
 const stats=el('div',undefined,'license-stats'),tabs=el('div',undefined,'licenses-tabs'),panel=el('div',undefined,'licenses-panel');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Secciones de Licencias Pro');panel.setAttribute('role','tabpanel');
 const defs=[['panel','Panel de vigencias','gauge'],['productos','Productos y catálogo','image'],['inventario','Inventario','list'],['ventas','Ventas','cart'],['entregas','Entregas','truck'],['notificaciones','Notificaciones de renovación','mail'],['historial','Historial','history']];
 for(const[key,label,icon]of defs){const tab=button('',()=>{licenseState.tab=key;paint();},'licenses-tab');tab.setAttribute('role','tab');tab.dataset.tab=key;tab.append(systemIcon(licenseIcons[icon]),el('span',label));tabs.append(tab);}
 tabs.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight'].includes(event.key))return;const list=[...tabs.children],at=list.indexOf(document.activeElement);if(at<0)return;event.preventDefault();const next=list[(at+(event.key==='ArrowRight'?1:list.length-1))%list.length];next.focus();next.click();});
 wrap.append(bar,stats,tabs,panel);
 function paintStats(){const d=licenseMeta.dashboard;stats.replaceChildren();for(const[key,label,state]of [['disponibles','Disponibles','disponible'],['reservadas','Reservadas','reservada'],['activas','Activas','activa'],['por_vencer','Por vencer','por_vencer'],['vencidas','Vencidas','vencida'],['renovaciones','Renovaciones realizadas','renovada'],...(d.revision?[['revision','En revisión','revision']]:[])]){
  const card=button('',()=>{if(key==='renovaciones')licenseState.tab='historial';else{licenseState.tab='inventario';licenseState.state=state;licenseState.page=1;}paint();},'license-stat');card.dataset.state=state;card.setAttribute('aria-pressed',String(licenseState.tab==='inventario'&&licenseState.state===state));card.title=key==='renovaciones'?'Ver el historial':'Filtrar el inventario: '+label.toLowerCase();card.append(el('strong',String(d[key])),el('span',label));stats.append(card);}}
 async function paint(){for(const tab of tabs.children){const on=tab.dataset.tab===licenseState.tab;tab.setAttribute('aria-selected',String(on));tab.tabIndex=on?0:-1;if(on)tab.scrollIntoView({block:'nearest',inline:'nearest'});}
  // El catálogo se dibuja al instante con los datos ya cargados: sin «Cargando…» intermedio (evita el parpadeo al actualizar existencias).
  paintStats();if(licenseState.tab!=='productos')panel.replaceChildren(el('p','Cargando…','system-muted'));
  try{const t=licenseState.tab;if(t==='panel')licensePanel(panel);else if(t==='productos')licenseProducts(panel);else if(t==='inventario')await licenseInventory(panel);else if(t==='ventas')await licenseSales(panel);else if(t==='entregas')await licenseDeliveries(panel);else if(t==='notificaciones')await licenseNotices(panel);else await licenseHistory(panel);}
  catch(error){panel.replaceChildren(el('p',error.message,'empty-module'));}}
 window.licenseReload=async()=>{try{await licenseLoadMeta();}catch(error){notify(error.message);}await paint();};await paint();
}
function licenseReloadAll(){if(typeof window.licenseReload==='function'&&document.querySelector('.licenses'))window.licenseReload();if(typeof window.clientLicensesReload==='function'&&document.querySelector('.client-licenses'))window.clientLicensesReload();}
function licensePanel(panel){panel.replaceChildren();const rows=licenseMeta.expiring||[],soon=licenseMeta.display?.soon_days||30;
 const settings=el('form',undefined,'license-threshold'),days=el('input'),save=el('button','Guardar','secondary');days.type='number';days.min='1';days.max='180';days.value=String(soon);days.setAttribute('aria-label','Días de aviso de próximo vencimiento');save.type='submit';
 const label=el('label');label.append(el('span','Aviso de próximo vencimiento (amarillo):'),days,el('span','días'));settings.append(label,save);
 settings.onsubmit=async event=>{event.preventDefault();save.disabled=true;try{await api('/api/licenses/settings',{soon_days:days.value});toast('Umbral guardado: '+days.value+' días.','success');window.licenseReload();}catch(error){toast(error.message,'error');}finally{save.disabled=false;}};
 panel.append(el('h2','Próximas renovaciones','license-section-title'),el('p','Licencias vendidas que vencen en los próximos '+soon+' días o ya vencidas sin renovar. Las perpetuas y las que aún no se activan no aparecen. Verde: vigente · amarillo: próxima a vencer · rojo: vencida · gris: sin activar.','license-hint'),settings);
 if(!rows.length){panel.append(el('p','No hay licencias por vencer en los próximos '+soon+' días.','empty-module'));return;}
 const list=el('div',undefined,'license-table');for(const row of rows){const state=row.days_left<0?'vencida':'por_vencer',item=el('article',undefined,'license-row'),head=el('div',undefined,'license-row-main');
  head.append(el('strong',row.code),el('span',row.product),licenseBadge(state));item.append(head,el('p',row.client||'Sin cliente','license-row-facts'),licenseMeter({...row,state,activated_at:'',purchased_at:''}));
  const actions=el('div',undefined,'license-row-actions');actions.append(button('Ver licencia',()=>licenseView(row.id),'text-action'),button('Renovar',()=>licenseRenewDialog({id:row.id,code:row.code,expires_at:row.expires_at}),'text-action'));item.append(actions);list.append(item);}
 panel.append(list);}
// Catálogo de licencias: tarjetas uniformes con logotipo grande, nombre en dos líneas como máximo (completo al pasar el cursor), detalles
// secundarios, cuatro indicadores reales de inventario (estados exclusivos calculados en el servidor: una licencia nunca cuenta dos veces),
// precio destacado y acciones en «Editar» + menú «⋯». Los nombres guardados no cambian; nunca se muestran credenciales.
