 const cols=[['','Imagen'],['nombre','Producto'],['fabricante','Fabricante'],['activacion','Activación'],['precio','Precio'],['disponibles','Disponibles'],['reservadas','Reservadas'],['vendidas','Vendidas'],['vencidas','Vencidas'],['','Acciones']];
